<?php
/** GD Client Portal v6.4.1 — Intelligent Inbox & Notification Actions. */
if (!defined('ABSPATH')) exit;

function gd_client_portal_inbox_items($limit=60){
    global $wpdb; $uid=gd_client_portal_cached_current_user_id(); if(!$uid || !gd_client_portal_verify_request()) return array();
    $limit=max(10,min(100,absint($limit))); $out=array();
    $add=function($kind,$id,$title,$body,$date,$unread=0,$url='',$priority='normal',$source='',$project_id=0)use(&$out){$out[]=array('kind'=>$kind,'id'=>absint($id),'title'=>wp_strip_all_tags($title),'body'=>wp_strip_all_tags($body),'date'=>$date,'unread'=>absint($unread),'url'=>$url,'priority'=>sanitize_key($priority),'source'=>sanitize_key($source),'project_id'=>absint($project_id));};
    if(function_exists('gd_client_portal_get_notifications')){
        foreach(gd_client_portal_get_notifications($uid,$limit) as $n){$url='';if(!empty($n->project_id)&&function_exists('gd_client_portal_get_dashboard_url'))$url=add_query_arg('project_id',absint($n->project_id),gd_client_portal_get_dashboard_url());$add('notification',$n->id,$n->title,$n->body,$n->created_at,!empty($n->is_read)?0:1,$url,'normal',$n->type,!empty($n->project_id)?$n->project_id:0);}
    }
    $tenant=absint(gd_client_portal_get_current_tenant_id()); $platform=gd_client_portal_is_platform_admin(); $tenant_admin=function_exists('gd_client_portal_user_is_tenant_admin')&&gd_client_portal_user_is_tenant_admin();
    if(function_exists('gdcp_message_service')){
        $rows=$platform ? gdcp_message_service()->list_for_tenant(0,$limit) : gdcp_message_service()->list_for_user($uid,$tenant,$tenant_admin,$limit);
        foreach($rows as $m){$author=gd_client_portal_cached_user($m->user_id);$add('message',$m->id,'Project message',($author?$author->display_name:'Portal user').': '.$m->message,$m->created_at,0,!empty($m->project_id)&&function_exists('gd_client_portal_get_dashboard_url')?add_query_arg('project_id',absint($m->project_id),gd_client_portal_get_dashboard_url()):'','normal','project',$m->project_id);}
    }
    if(function_exists('gdcp_inbox_read_service')){
        $rows=gdcp_inbox_read_service()->support($uid,$tenant,$tenant_admin,$platform,$limit);
        foreach($rows as $t){$add('support',$t->id,'Support: '.$t->subject,'Status: '.ucwords(str_replace('_',' ',$t->status)),$t->updated_at,0,'','normal',$t->priority,$t->project_id);}
        $rows=gdcp_inbox_read_service()->invoices($uid,$tenant,$tenant_admin,$platform,$limit);
        foreach($rows as $inv){$url=add_query_arg('gdcp_invoice_pdf',absint($inv->id),home_url('/'));$balance=max(0,(float)$inv->total-(float)$inv->amount_paid);$priority=($inv->due_date && strtotime($inv->due_date.' 23:59:59')<current_time('timestamp'))?'urgent':'high';$add('invoice',$inv->id,'Invoice '.$inv->invoice_number,sprintf('Outstanding balance: %s %s%s',number_format($balance,2),strtoupper($inv->currency),$inv->due_date?' · Due '.$inv->due_date:''),$inv->updated_at,0,$url,$priority,'billing',$inv->project_id);}
        if($platform || $tenant_admin){$rows=gdcp_inbox_read_service()->automation($tenant,$platform,$limit);foreach($rows as $q){$project=$q->project_id?gd_client_portal_get_project_by_id($q->project_id):null;if($project && !gd_client_portal_verify_project_access($project))continue;$add('automation',$q->id,$q->status==='failed'?'Automation failed':'Automation running',$q->event_key.' · Attempt '.absint($q->attempts).'/'.absint($q->max_attempts),$q->updated_at,0,$project?gd_client_portal_operations_project_url($project->id):'',$q->status==='failed'?'urgent':'high','automation',$q->project_id);}}
        $rows=gdcp_inbox_read_service()->approvals($uid,$tenant,$tenant_admin,$platform,$limit);foreach($rows as $a){$url=function_exists('gd_client_portal_get_dashboard_url')?add_query_arg('project_id',absint($a->project_id),gd_client_portal_get_dashboard_url()):'';$add('approval',$a->id,'Approval required','Project #'.absint($a->project_id).' · Version '.absint($a->version),$a->created_at,1,$url,'high','approval',$a->project_id);}
    }
    usort($out,function($a,$b){$u=($b['unread']<=>$a['unread']);if($u)return $u;$p=array('urgent'=>4,'high'=>3,'normal'=>2,'low'=>1);$pp=($p[$b['priority']]??2)<=>($p[$a['priority']]??2);if($pp)return $pp;return strcmp((string)$b['date'],(string)$a['date']);});
    return array_slice($out,0,$limit);
}
function gd_client_portal_inbox_unread(){ $items=gd_client_portal_inbox_items(100);$n=0;foreach($items as $i)$n+=(int)$i['unread'];return $n; }
function gd_client_portal_inbox_mark_read_ajax(){
    gd_client_portal_ajax_guard('gd_client_portal_inbox','nonce');$id=absint($_POST['notification_id']??0);
    if(!$id||!function_exists('gd_client_portal_notifications_table'))wp_send_json_error(array('message'=>'Invalid notification.'));
    $ok=function_exists('gdcp_notification_service')?gdcp_notification_service()->mark_read($id,gd_client_portal_cached_current_user_id()):false;
    wp_send_json_success(array('unread'=>function_exists('gd_client_portal_get_unread_notification_count')?gd_client_portal_get_unread_notification_count():0,'changed'=>$ok!==false));
}
function gd_client_portal_inbox_mark_all_ajax(){
    gd_client_portal_ajax_guard('gd_client_portal_inbox','nonce');
    if(function_exists('gdcp_notification_service'))gdcp_notification_service()->mark_all_read(gd_client_portal_cached_current_user_id());
    wp_send_json_success(array('unread'=>0));
}
add_action('wp_ajax_gd_client_portal_inbox_mark_read','gd_client_portal_inbox_mark_read_ajax');
add_action('wp_ajax_gd_client_portal_inbox_mark_all','gd_client_portal_inbox_mark_all_ajax');
function gd_client_portal_inbox_action_ajax(){
    gd_client_portal_ajax_guard('gd_client_portal_inbox','nonce');
    $kind=sanitize_key(wp_unslash($_POST['kind']??''));$id=absint($_POST['id']??0);$action=sanitize_key(wp_unslash($_POST['action_type']??''));$project_id=absint($_POST['project_id']??0);
    $uid=gd_client_portal_cached_current_user_id();$is_admin=gd_client_portal_is_platform_admin()||gd_client_portal_user_is_tenant_admin();
    if($kind==='approval'){
        $project=gd_client_portal_get_project_by_id($project_id);$approval=function_exists('gd_client_portal_get_active_approval')?gd_client_portal_get_active_approval($project_id):false;
        if(!$project||!$approval||absint($approval->id)!==$id||!function_exists('gd_client_portal_approval_client_can_act')||!gd_client_portal_approval_client_can_act($project))wp_send_json_error(array('message'=>'Approval access denied.'),403);
        if(!in_array($action,array('approval_approve','approval_revision'),true))wp_send_json_error(array('message'=>'Invalid approval action.'));
        $decision=$action==='approval_approve'?'approved':'revision_requested';$comment=sanitize_textarea_field(wp_unslash($_POST['comment']??''));
        $service=function_exists('gdcp_service')?gdcp_service('approval'):null;
        if(!$service||!method_exists($service,'decide'))wp_send_json_error(array('message'=>'Approval workflow unavailable.'),500);
        $result=$service->decide($project_id,$decision,$comment);
        if(empty($result['ok']))wp_send_json_error(array('message'=>$result['message']??'Could not save the approval decision.'),absint($result['code']??409));
        do_action('gd_client_portal_approval_decided',$project_id,$decision,$comment);wp_send_json_success(array('message'=>$decision==='approved'?'Project approved.':'Revision request submitted.','remove'=>true));
    }
    if($kind==='project'){
        $project=gd_client_portal_get_project_by_id($project_id);if(!$project||!gd_client_portal_verify_project_access($project))wp_send_json_error(array('message'=>'Project access denied.'),403);
        if($action==='advance_stage'&&$is_admin){$workflow=gd_client_portal_get_workflow($project->service_type);$idx=array_search($project->current_stage,$workflow,true);if($idx===false||empty($workflow[$idx+1]))wp_send_json_error(array('message'=>'Project is already at the final stage.'));$next=$workflow[$idx+1];if(!gd_client_portal_update_project_stage($project_id,$next,gd_client_portal_auto_progress($project->service_type,$next)))wp_send_json_error(array('message'=>'Could not advance the project.'));wp_send_json_success(array('message'=>'Project advanced.','remove'=>false));}
        if($action==='assign'&&$is_admin){$user_id=absint($_POST['user_id']??0);$role=sanitize_key($_POST['role']??'lead');if(!in_array($role,array('lead','member'),true)||!function_exists('gd_client_portal_set_project_assignment')||!gd_client_portal_set_project_assignment($project_id,$user_id,$role))wp_send_json_error(array('message'=>'Could not assign the project.'));wp_send_json_success(array('message'=>'Project assignment updated.'));}
        wp_send_json_error(array('message'=>'Invalid project action.'),400);
    }
    if($kind==='support'){
        if(!function_exists('gd_client_portal_support_ticket'))wp_send_json_error(array('message'=>'Support module unavailable.'),500);$ticket=gd_client_portal_support_ticket($id);if(!$ticket||!function_exists('gd_client_portal_support_access')||!gd_client_portal_support_access($ticket,$is_admin))wp_send_json_error(array('message'=>'Support access denied.'),403);global $wpdb;$now=current_time('mysql');
        if($action==='support_resolve'){if(!$is_admin)wp_send_json_error(array('message'=>'Only support staff can resolve tickets.'),403);if(!gd_client_portal_support_service()->resolve($ticket))wp_send_json_error(array('message'=>'Ticket could not be resolved.'),500);if(function_exists('gd_client_portal_create_notification'))gd_client_portal_create_notification($ticket->user_id,'Support ticket resolved',$ticket->subject,'support_ticket',$ticket->project_id,$ticket->tenant_id);wp_send_json_success(array('message'=>'Ticket resolved.','remove'=>true));}
        if($action==='support_reply'){$body=sanitize_textarea_field(wp_unslash($_POST['body']??''));if(!$body)wp_send_json_error(array('message'=>'Reply message is required.'));$internal=$is_admin&&!empty($_POST['internal'])?1:0;if(!gd_client_portal_support_service()->reply($ticket,$uid,$body,$is_admin,$internal))wp_send_json_error(array('message'=>'Reply could not be saved.'),500);if(function_exists('gd_client_portal_create_notification')){if($is_admin)gd_client_portal_create_notification($ticket->user_id,'Support team replied',$ticket->subject,'support_ticket',$ticket->project_id,$ticket->tenant_id);else foreach(gd_client_portal_support_managers($ticket->tenant_id) as $manager_id)gd_client_portal_create_notification($manager_id,'Client replied to support ticket',$ticket->subject,'support_ticket',$ticket->project_id,$ticket->tenant_id);}wp_send_json_success(array('message'=>'Reply posted.'));}
    }
    if($kind==='automation'&&$is_admin){if(!function_exists('gdcp_automation_service'))wp_send_json_error(array('message'=>'Automation module unavailable.'),500);$row=gdcp_automation_service()->get_queue($id);if(!$row)wp_send_json_error(array('message'=>'Queue item not found.'),404);$platform_admin=gd_client_portal_is_platform_admin();$current_tenant=absint(gd_client_portal_get_current_tenant_id());if(!$platform_admin&&($current_tenant<=0||absint($row->tenant_id)!==$current_tenant))wp_send_json_error(array('message'=>'Automation queue access denied.'),403);if($project_id){$project=gd_client_portal_get_project_by_id($project_id);if(!$project||!gd_client_portal_verify_project_access($project)||absint($project->tenant_id)!==absint($row->tenant_id))wp_send_json_error(array('message'=>'Project access denied.'),403);}if($action==='automation_retry'&&$row->status==='failed'){if(function_exists('gdcp_automation_service')&&!gdcp_automation_service()->retry_queue($id))wp_send_json_error(array('message'=>'Unable to queue automation retry.'),500);wp_schedule_single_event(time()+2,'gd_client_portal_automation_queue_runner',array($id));wp_send_json_success(array('message'=>'Automation queued for retry.','remove'=>true));}if($action==='automation_cancel'&&in_array($row->status,array('queued','running'),true)){if(function_exists('gdcp_automation_service')&&!gdcp_automation_service()->cancel_queue($id))wp_send_json_error(array('message'=>'Unable to cancel automation.'),500);wp_send_json_success(array('message'=>'Automation cancelled.','remove'=>true));}wp_send_json_error(array('message'=>'Invalid automation action.'));}
    if($kind==='invoice'){
        if(!function_exists('gd_client_portal_payment_invoice'))wp_send_json_error(array('message'=>'Billing module unavailable.'),500);$invoice=gd_client_portal_payment_invoice($id);if(!$invoice||!function_exists('gd_client_portal_payment_access')||!gd_client_portal_payment_access($invoice))wp_send_json_error(array('message'=>'Invoice access denied.'),403);if($action!=='invoice_pay')wp_send_json_error(array('message'=>'Invalid invoice action.'));if(!function_exists('gd_client_portal_paystack_initialize'))wp_send_json_error(array('message'=>'Online payment is unavailable.'));$response=gd_client_portal_paystack_initialize($invoice);if(is_wp_error($response))wp_send_json_error(array('message'=>$response->get_error_message()),400);$body=json_decode(wp_remote_retrieve_body($response),true);if(wp_remote_retrieve_response_code($response)!==200||empty($body['status'])||empty($body['data']['authorization_url']))wp_send_json_error(array('message'=>$body['message']??'Unable to start payment.'),400);wp_send_json_success(array('message'=>'Payment page ready.','redirect'=>esc_url_raw($body['data']['authorization_url'])));
    }
    wp_send_json_error(array('message'=>'Unsupported inbox action.'),400);
}
add_action('wp_ajax_gd_client_portal_inbox_action','gd_client_portal_inbox_action_ajax');
function gd_client_portal_inbox_count_ajax(){
    if(!is_user_logged_in()||!gd_client_portal_verify_request()) wp_send_json_error(array('message'=>'Access denied.'),403);
    check_ajax_referer('gd_client_portal_inbox','nonce');
    wp_send_json_success(array('unread'=>gd_client_portal_inbox_unread()));
}
