function gd_client_portal_render_inbox($atts=array(),$admin=false){
    if(!gd_client_portal_verify_request()||!gd_client_portal_verify_tenant_access())return gd_client_portal_render_access_gate();
    wp_enqueue_style('gd-client-portal-inbox');wp_enqueue_script('gd-client-portal-inbox');$items=gd_client_portal_inbox_items(60);$nonce=wp_create_nonce('gd_client_portal_inbox');
    ob_start();?><div class="gdcp-inbox" data-nonce="<?php echo esc_attr($nonce); ?>" data-admin="<?php echo $admin?1:0; ?>"><header class="gdcp-inbox-head"><div><span class="gdcp-inbox-eyebrow">Workspace</span><h2><?php esc_html_e('Unified Inbox','gd-client-portal'); ?></h2><p><?php esc_html_e('Notifications, project messages, approvals and support activity in one focused queue.','gd-client-portal'); ?></p></div><div class="gdcp-inbox-actions"><span class="gdcp-inbox-count" aria-live="polite"><?php echo esc_html(gd_client_portal_inbox_unread()); ?> unread</span><button type="button" class="gdcp-inbox-refresh">Refresh</button><button type="button" class="gdcp-inbox-mark-all">Mark all read</button></div></header>
<div class="gdcp-inbox-tools"><label class="gdcp-inbox-search"><span>Search inbox</span><input type="search" class="gdcp-inbox-search-input" placeholder="Search projects, messages, invoices…" autocomplete="off"></label></div><div class="gdcp-inbox-filters"><button type="button" class="is-active" data-filter="all">All</button><button type="button" data-filter="unread">Unread</button><button type="button" data-filter="notification">Notifications</button><button type="button" data-filter="message">Messages</button><button type="button" data-filter="approval">Approvals</button><button type="button" data-filter="support">Support</button></div>
<div class="gdcp-inbox-list"><?php if(!$items):?><div class="gdcp-inbox-empty"><strong>You're all caught up.</strong><span>New activity will appear here.</span></div><?php endif;foreach($items as $i):?><article class="gdcp-inbox-item <?php echo $i['unread']?'is-unread':''; ?> priority-<?php echo esc_attr($i['priority']); ?>" data-kind="<?php echo esc_attr($i['kind']); ?>" data-unread="<?php echo $i['unread']?'1':'0'; ?>" data-id="<?php echo esc_attr($i['id']); ?>" data-project-id="<?php echo esc_attr(!empty($i['project_id'])?$i['project_id']:0); ?>" data-title="<?php echo esc_attr($i['title']); ?>" data-body="<?php echo esc_attr($i['body']); ?>" data-date="<?php echo esc_attr($i['date']); ?>" data-source="<?php echo esc_attr($i['source']); ?>" data-priority="<?php echo esc_attr($i['priority']); ?>"><div class="gdcp-inbox-icon" aria-hidden="true"><?php echo $i['kind']==='message'?'↗':($i['kind']==='approval'?'✓':($i['kind']==='support'?'?':($i['kind']==='invoice'?'$':($i['kind']==='automation'?'⚙':'•')))); ?></div><div class="gdcp-inbox-main"><div class="gdcp-inbox-meta"><span class="gdcp-inbox-type"><?php echo esc_html(ucwords($i['kind'])); ?></span><time><?php echo esc_html($i['date']); ?></time></div><h3><?php echo esc_html($i['title']); ?></h3><p><?php echo esc_html($i['body']); ?></p><div class="gdcp-inbox-item-actions"><button type="button" class="gdcp-inbox-details">Details</button><?php if($i['url']):?><a class="gdcp-inbox-open" href="<?php echo esc_url($i['url']); ?>">Open →</a><?php endif; ?><?php if($i['kind']==='approval' && !$admin): ?><button type="button" class="gdcp-inbox-action" data-action="approval_approve">Approve</button><button type="button" class="gdcp-inbox-action secondary" data-action="approval_revision">Request revision</button><?php elseif($i['kind']==='invoice' && !$admin): ?><button type="button" class="gdcp-inbox-action" data-action="invoice_pay">Pay invoice</button><?php elseif($i['kind']==='support'): ?><button type="button" class="gdcp-inbox-action" data-action="support_reply">Reply</button><?php if($admin): ?><button type="button" class="gdcp-inbox-action secondary" data-action="support_resolve">Resolve</button><?php endif; ?><?php elseif($i['kind']==='automation' && $admin): ?><button type="button" class="gdcp-inbox-action" data-action="automation_retry">Retry</button><button type="button" class="gdcp-inbox-action secondary" data-action="automation_cancel">Cancel</button><?php elseif($i['kind']==='message' && $admin): ?><button type="button" class="gdcp-inbox-action" data-action="project_open">Open project</button><?php endif; ?></div></div><?php if($i['kind']==='notification'&&$i['unread']):?><button type="button" class="gdcp-inbox-read">Read</button><?php endif;?></article><?php endforeach;?></div><aside class="gdcp-inbox-drawer" aria-hidden="true"><div class="gdcp-inbox-drawer-backdrop"></div><section class="gdcp-inbox-drawer-panel" role="dialog" aria-modal="true" aria-label="Inbox details"><button type="button" class="gdcp-inbox-drawer-close" aria-label="Close">×</button><span class="gdcp-inbox-drawer-type"></span><h3 class="gdcp-inbox-drawer-title"></h3><time class="gdcp-inbox-drawer-date"></time><p class="gdcp-inbox-drawer-body"></p><dl class="gdcp-inbox-drawer-meta"><div><dt>Priority</dt><dd class="gdcp-inbox-drawer-priority"></dd></div><div><dt>Source</dt><dd class="gdcp-inbox-drawer-source"></dd></div><div><dt>Project</dt><dd class="gdcp-inbox-drawer-project"></dd></div></dl><div class="gdcp-inbox-drawer-actions"></div></section></aside></div><?php return ob_get_clean();
}
function gd_client_portal_inbox_shortcode($atts=array()){return gd_client_portal_render_inbox($atts,false);}
